---MAIN---
   1 /* Syscalls on every mode -- one binary, three channels.
   2  *
   3  * The andesim runtime routes newlib syscalls through MMIO devices both
   4  * engines model, so the SAME ELF gets working stdio, file io and exit
   5  * codes on fast (QEMU), cycle (vsim) and hybrid:
   6  *
   7  *   stdout        UART2 (0xf0300020) -- printf goes to your terminal
   8  *   file io       HTIF magicmem (0xe0080010), served host-side: fopen/
   9  *                 fread/fwrite hit REAL files in the working directory
  10  *   time          gettimeofday(), same HTIF channel, host clock
  11  *   exit code     SimControl (0xe0080000) -- main's return value becomes
  12  *                 the andesim exit code on fast and cycle
  13  *
  14  * Hybrid adds two rules, which this demo demonstrates:
  15  *   - an open FILE* must be CLOSED before the handoff. Host file
  16  *     descriptors live in the engine process and do not cross to vsim;
  17  *     a closed file lives on the host filesystem, which both engines
  18  *     share.
  19  *   - a hybrid run ENDS at the ROI exit trigger (that is where the
  20  *     cycle figure is drained), so code after the ROI never runs on
  21  *     hybrid. Anything that must happen -- here the file cleanup --
  22  *     belongs inside the ROI; the hybrid pass/fail signal is the
  23  *     printed SYSCALL_OK, not main's return value.
  24  *
  25  * QEMU phase (before the ROI):
  26  *   - gettimeofday() seeds a payload no compiler can precompute
  27  *   - fwrite the payload to syscall_demo.tmp, fclose it
  28  *
  29  * vsim ROI:
  30  *   - printf INSIDE the ROI (its UART cycles are simply part of the
  31  *     figure)
  32  *   - fopen/fread the file back, compare with the in-DRAM copy (the copy
  33  *     crossed the handoff in the shared mmap; the file crossed on the
  34  *     host filesystem), remove it; prints SYSCALL_OK / SYSCALL_BAD
  35  */
  36 
  37 #include <stdint.h>
  38 #include <stdio.h>
  39 #include <string.h>
  40 #include <sys/time.h>
  41 #include <andesim/ROI.h>
  42 
  43 #define PATH "syscall_demo.tmp"
  44 
  45 static char payload[64];
  46 
  47 /* ROI body, noinline and non-static so --trigger pc can name it. */
  48 __attribute__((noinline)) int syscall_roi(void)
  49 {
  50   printf("printf inside the ROI\n");
  51 
  52   char back[sizeof payload];
  53   memset(back, 0, sizeof back);
  54   FILE *f = fopen(PATH, "r");
  55   if (!f) {
  56     printf("SYSCALL_BAD fopen\n");
  57     return 1;
  58   }
  59   size_t n = fread(back, 1, sizeof back, f);
  60   fclose(f);
  61 
  62   size_t want = strlen(payload);
  63   if (n != want || memcmp(back, payload, want) != 0) {
  64     printf("SYSCALL_BAD readback n=%u\n", (unsigned) n);
  65     return 1;
  66   }
  67   /* Cleanup lives INSIDE the ROI: on hybrid nothing after the ROI runs. */
  68   if (remove(PATH) != 0) {
  69     printf("SYSCALL_BAD remove\n");
  70     return 1;
  71   }
  72   printf("SYSCALL_OK bytes=%u\n", (unsigned) want);
  73   return 0;
  74 }
  75 
  76 int main(void)
  77 {
  78   struct timeval tv;
  79   if (gettimeofday(&tv, NULL) != 0) {
  80     printf("SYSCALL_STAGE_BAD gettimeofday\n");
  81     return 2;
  82   }
  83   snprintf(payload, sizeof payload, "syscall demo t=%lx.%06lx\n",
  84            (unsigned long) tv.tv_sec, (unsigned long) tv.tv_usec);
  85 
  86   FILE *f = fopen(PATH, "w");
  87   if (!f) {
  88     printf("SYSCALL_STAGE_BAD fopen\n");
  89     return 2;
  90   }
  91   size_t want = strlen(payload);
  92   size_t n = fwrite(payload, 1, want, f);
  93   fclose(f); /* MUST close before the ROI: fds do not cross the handoff. */
  94   if (n != want) {
  95     printf("SYSCALL_STAGE_BAD short write\n");
  96     return 2;
  97   }
  98   printf("SYSCALL staged\n");
  99 
 100   andesim_ROI_begin();
 101   int rc = syscall_roi();
 102   andesim_ROI_end();
 103   /* ROI end symbol for --pc-end: the point right after the call. */
 104   __asm__ __volatile__(".globl syscall_roi_end\nsyscall_roi_end:" ::: "memory");
 105 
 106   /* Runs on fast and cycle only: a hybrid run ended at the exit trigger. */
 107   return rc; /* exit code travels via SimControl */
 108 }
---MAKEFILE---
   1 -include ../../Make.var
   2 
   3 all: syscall.elf syscall.dump
   4 
   5 syscall.elf: main.c
   6     $(CC) $(CFLAGS) $< -o $@
   7 
   8 syscall.dump: syscall.elf
   9     $(OBJDUMP) -d $< > $@
  10 
  11 # The four andesim modes, one target each. Same ELF everywhere.
  12 syscall-fast: syscall.elf
  13     $(ANDESIM_BIN) --mode fast $(ANDESIM_FLAGS) $<
  14 
  15 syscall-cycle: syscall.elf
  16     $(ANDESIM_BIN) --mode cycle --engine $(ENGINE) $(ANDESIM_FLAGS) $<
  17 
  18 syscall-hybrid-marker: syscall.elf
  19     $(ANDESIM_BIN) --mode hybrid --trigger marker --engine $(ENGINE) $(ANDESIM_FLAGS) $<
  20 
  21 syscall-hybrid-pc: syscall.elf
  22     $(ANDESIM_BIN) --mode hybrid --trigger pc \
  23         --pc-start syscall_roi --pc-end syscall_roi_end \
  24         --engine $(ENGINE) $(ANDESIM_FLAGS) $<
  25 
  26 run: syscall-fast syscall-cycle syscall-hybrid-marker syscall-hybrid-pc
  27 
  28 clean:
  29     - rm -f syscall.elf syscall.dump syscall_demo.tmp
  30 
  31 .PHONY: all run clean syscall-fast syscall-cycle syscall-hybrid-marker syscall-hybrid-pc

