1	/* vplat: one newlib syscall layer that works on EVERY engine.
2	 *
3	 * Replaces -lgloss_vh (semihosting) so a single ELF runs unmodified on
4	 * QEMU (fast), vsim (cycle) and across a hybrid handoff. It only touches
5	 * channels both engines model at the same addresses:
6	 *
7	 *   stdio (fd 0-2)  ATCUART100 UART2: THR @0xf0300020, LSR @0xf0300034.
8	 *                   QEMU: serial_mm_init(UART2+0x20, shift 2) = serial_hd(0);
9	 *                   vsim: src/platform/uart.hpp (vsim repo) -> host stdout.
10	 *   exit            SimControl @0xe0080000: u32 exit code (<256).
11	 *                   vsim: sim_control.hpp; QEMU: hw/riscv/andes_ae350.c
12	 *                   (sim_ctrl_write).
13	 *   file io (fd>2)  HTIF magicmem command @0xe0080010, served host-side
14	 *                   (vsim: sim_control.hpp syscall table; QEMU: the same
15	 *                   table in andes_ae350.c's andesim_htif_syscall).
16	 *
17	 * No semihosting, no ecall, and no "which engine am I on" probe -- hybrid
18	 * migrates the running process between engines, so any boot-time detection
19	 * would go stale at the handoff. Every call must be engine-blind.
20	 */
21	
22	#include <stdint.h>
23	#include <stddef.h>
24	#include <sys/stat.h>
25	#include <unistd.h>
26	
27	/* ---- UART2 (console) ------------------------------------------------- */
28	
29	#define UART_THR (*(volatile uint32_t*) 0xf0300020UL)
30	#define UART_LSR (*(volatile uint32_t*) 0xf0300034UL)
31	#define UART_LSR_THRE 0x20u
32	
33	static void uart_putc(char c)
34	{
35	  while (!(UART_LSR & UART_LSR_THRE))
36	    ;
37	  UART_THR = (uint32_t) (unsigned char) c;
38	}
39	
40	/* ---- SimControl / HTIF ------------------------------------------------ */
41	
42	#define SIM_EXIT_ADDR   0xe0080000UL
43	#define HTIF_TOHOST_CMD 0xe0080010UL
44	
45	/* HTIF syscall numbers -- must match the table in the vsim repo's
46	 * src/platform/sim_control.hpp (and the QEMU mirror device). */
47	#define VH_SYS_GETTIMEOFDAY 5
48	#define VH_SYS_OPEN         6
49	#define VH_SYS_WRITE        7
50	#define VH_SYS_GETCWD       8
51	#define VH_SYS_LSEEK        9
52	#define VH_SYS_READ         10
53	#define VH_SYS_FLEN         11
54	#define VH_SYS_CLOSE        12
55	#define VH_SYS_ACCESS       13
56	#define VH_SYS_FACCESSAT    14
57	#define VH_SYS_FSTAT        15
58	#define VH_SYS_FSTATAT      16
59	#define VH_SYS_LINK         17
60	#define VH_SYS_LSTAT        18
61	#define VH_SYS_STAT         19
62	#define VH_SYS_OPENAT       20
63	#define VH_SYS_RENAME       21
64	#define VH_SYS_UNLINK       22
65	
66	static uint64_t magicmem[8] __attribute__((aligned(64)));
67	
68	/* The host (SimControl) reads magicmem straight from RAM, behind the
69	 * hart's caches, so write back L1 (and L2 if present) before handing the
70	 * command over. CCTL command 6 = L1D_WBINVAL_ALL, 0x12 = L2_WBINVAL_ALL.
71	 * On QEMU the CSR write is accepted and memory is coherent anyway. */
72	static void flush_dcache(void)
73	{
74	  __asm__ __volatile__("csrw mcctlcommand, %0" ::"rK"(6));
75	#if __riscv_xlen == 64
76	  /* L2 writeback, gated to rv64 because it uses rv64-only ld/sd to reach the
77	   * 64-bit L2C MMIO registers (mmsc_cfg bit 46 is the L2-present flag) -- it
78	   * cannot COMPILE on rv32. Whether to flush is still decided at runtime by the
79	   * bit-46 check inside the asm. An rv32 core WITH an L2C would need a
80	   * 32-bit-halves access path here; today's rv32 target (d23) has no L2, so the
81	   * L1 writeback above suffices. */
82	  __asm__ __volatile__(
83	    "csrr    t0, mmsc_cfg\n"
84	    "li      t1, 1\n"
85	    "slli    t1, t1, 46\n"
86	    "and     t2, t0, t1\n"
87	    "beqz    t2, 1f\n"
88	    "li      t3, 0xe0500008\n"   /* L2C_REG_CTL: enabled? */
89	    "ld      t4, 0(t3)\n"
90	    "andi    t4, t4, 1\n"
91	    "beqz    t4, 1f\n"
92	    "li      t5, 0xe0500040\n"   /* L2C_REG_CCTL <- WBINVAL_ALL */
93	    "li      t6, 0x12\n"
94	    "sd      t6, 0(t5)\n"
95	    "2:\n"
96	    "li      t2, 0xe0500080\n"   /* poll L2C_REG_CCTL_M0_ST until idle */
97	    "ld      t3, 0(t2)\n"
98	    "andi    t3, t3, 0xF\n"
99	    "li      t5, 1\n"
100	    "beq     t3, t5, 2b\n"
101	    "1:\n" ::: "t0", "t1", "t2", "t3", "t4", "t5", "t6", "memory");
102	#endif
103	}
104	
105	static intptr_t htif_syscall(uint64_t n, uintptr_t a0, uintptr_t a1,
106	                             uintptr_t a2, uintptr_t a3)
107	{
108	  magicmem[0] = n;
109	  magicmem[1] = a0;
110	  magicmem[2] = a1;
111	  magicmem[3] = a2;
112	  magicmem[4] = a3;
113	  magicmem[5] = 0;
114	  magicmem[6] = 0;
115	  magicmem[7] = 0;
116	  flush_dcache();
117	  *(volatile uint64_t*) HTIF_TOHOST_CMD = (uintptr_t) magicmem;
118	  __asm__ __volatile__("fence rw,rw" ::: "memory");
119	  return (intptr_t) magicmem[0];
120	}
121	
122	/* ---- newlib stubs ------------------------------------------------------ */
123	
124	__attribute__((used)) ssize_t _write(int fd, const void* ptr, size_t len)
125	{
126	  if (fd > 2)
127	    return htif_syscall(VH_SYS_WRITE, fd, (uintptr_t) ptr, len, 0);
128	  for (size_t i = 0; i < len; ++i)
129	    uart_putc(((const char*) ptr)[i]);
130	  return (ssize_t) len;
131	}
132	
133	__attribute__((used)) ssize_t _read(int fd, void* buf, size_t len)
134	{
135	  if (fd > 2)
136	    return htif_syscall(VH_SYS_READ, fd, (uintptr_t) buf, len, 0);
137	  return 0; /* no console input on either engine: EOF */
138	}
139	
140	__attribute__((used)) int _fstat(int fd, struct stat* st)
141	{
142	  if (fd > 2)
143	    return (int) htif_syscall(VH_SYS_FSTAT, fd, (uintptr_t) st, 0, 0);
144	  st->st_mode = S_IFCHR; /* char device -> newlib line-buffers stdout */
145	  return 0;
146	}
147	
148	__attribute__((used)) int _isatty(int fd) { return fd <= 2; }
149	
150	__attribute__((used)) int _close(int fd)
151	{
152	  if (fd > 2)
153	    return (int) htif_syscall(VH_SYS_CLOSE, fd, 0, 0, 0);
154	  return 0;
155	}
156	
157	__attribute__((used)) off_t _lseek(int fd, off_t offset, int dir)
158	{
159	  if (fd > 2)
160	    return htif_syscall(VH_SYS_LSEEK, fd, offset, dir, 0);
161	  return 0;
162	}
163	
164	__attribute__((used)) int _open(const char* name, int flags, int mode, ...)
165	{
166	  return (int) htif_syscall(VH_SYS_OPEN, (uintptr_t) name, flags, mode, 0);
167	}
168	
169	__attribute__((used)) int _openat(int dirfd, const char* name, int flags, ...)
170	{
171	  return (int) htif_syscall(VH_SYS_OPENAT, dirfd, (uintptr_t) name, flags, 0);
172	}
173	
174	__attribute__((used)) int _stat(const char* file, struct stat* st)
175	{
176	  return (int) htif_syscall(VH_SYS_STAT, (uintptr_t) file, (uintptr_t) st, 0, 0);
177	}
178	
179	__attribute__((used)) int _lstat(const char* file, struct stat* st)
180	{
181	  return (int) htif_syscall(VH_SYS_LSTAT, (uintptr_t) file, (uintptr_t) st, 0, 0);
182	}
183	
184	__attribute__((used)) int _fstatat(int dirfd, const char* file,
185	                                   struct stat* st, int flags)
186	{
187	  return (int) htif_syscall(VH_SYS_FSTATAT, dirfd, (uintptr_t) file,
188	                            (uintptr_t) st, flags);
189	}
190	
191	__attribute__((used)) int _access(const char* file, int mode)
192	{
193	  return (int) htif_syscall(VH_SYS_ACCESS, (uintptr_t) file, mode, 0, 0);
194	}
195	
196	__attribute__((used)) int _faccessat(int dirfd, const char* file, int mode,
197	                                     int flags)
198	{
199	  return (int) htif_syscall(VH_SYS_FACCESSAT, dirfd, (uintptr_t) file, mode,
200	                            flags);
201	}
202	
203	__attribute__((used)) int _link(const char* oldn, const char* newn)
204	{
205	  return (int) htif_syscall(VH_SYS_LINK, (uintptr_t) oldn, (uintptr_t) newn, 0, 0);
206	}
207	
208	__attribute__((used)) int _unlink(const char* file)
209	{
210	  return (int) htif_syscall(VH_SYS_UNLINK, (uintptr_t) file, 0, 0, 0);
211	}
212	
213	__attribute__((used)) int _rename(const char* oldn, const char* newn)
214	{
215	  return (int) htif_syscall(VH_SYS_RENAME, (uintptr_t) oldn, (uintptr_t) newn,
216	                            0, 0);
217	}
218	
219	__attribute__((used)) int _getcwd(const char* buf, int size)
220	{
221	  return (int) htif_syscall(VH_SYS_GETCWD, (uintptr_t) buf, size, 0, 0);
222	}
223	
224	__attribute__((used)) int _gettimeofday(struct timeval* tp, void* tzp)
225	{
226	  return (int) htif_syscall(VH_SYS_GETTIMEOFDAY, (uintptr_t) tp,
227	                            (uintptr_t) tzp, 0, 0);
228	}
229	
230	__attribute__((used)) int _kill(int pid, int sig)
231	{
232	  (void) pid;
233	  (void) sig;
234	  return -1;
235	}
236	
237	__attribute__((used)) int _getpid(void) { return 1; }
238	
239	__attribute__((used)) void* _sbrk(intptr_t increment)
240	{
241	  extern char _end[];
242	  static char* p = _end;
243	  void* base = p;
244	  p += increment;
245	  return base;
246	}
247	
248	/* Exit codes stay below 256: sim_control.hpp treats any command < 256 as
249	 * the raw exit code (the 0x0123456x magic commands live above). */
250	__attribute__((used, noreturn)) void _exit(int exit_status)
251	{
252	  *(volatile uint32_t*) SIM_EXIT_ADDR = (uint32_t) exit_status & 0xff;
253	  for (;;)
